def cw(a): return [list(x) for x in zip(*a[::-1])]
def rot(a,n):
 for _ in range(n): a=cw(a)
 return a
names=[[2,1,2],[3,0,3],[2,1,2]]
out=[]
for row in names:
 tiles=[rot([r[:] for r in A],n) for n in row]
 for i in range(3): out.append(sum((t[i] for t in tiles),[]))
